mapper.update:
UPDATE biz01_promo
   SET biz01_provide_pur_cd     = #{req.providePurCode}
     , biz01_provide_content_cd = #{req.provideContentCode}
     , biz01_account_code_id    = #{req.accountCodeId}
     , biz01_note               = #{req.note}
 WHERE biz01_promo_id   = #{promoId}
   AND biz01_company_id = #{companyId}

UPDATE biz01_promo
   SET biz01_note = #{note}
 WHERE biz01_promo_id   = #{promoId}
   AND biz01_company_id = #{companyId}

UPDATE biz01_promo
   SET biz01_provide_pur_cd     = #{providePurCode}
     , biz01_provide_content_cd = #{provideContentCode}
     , biz01_account_code_id    = #{accountId}
     , biz01_tax_type           = #{taxType}
     , biz01_note               = #{note}
 WHERE biz01_promo_id   = #{promoId}
   AND biz01_company_id = #{companyId}

UPDATE biz01_promo
   SET biz01_provide_pur_cd     = #{providePurCode}
     , biz01_provide_content_cd = #{provideContentCode}
     , biz01_account_code_id    = #{accountId}
     , biz01_note               = #{note}
 WHERE biz01_promo_id   = #{promoId}
